Focus Area: {{ $json.focus || 'Not specified' }}
Target Audience: {{ $json.target_audience || 'Recommend the best-fit audience from the reports' }}
Seasonal Context: {{ $json.seasonal_context || 'No seasonal context specified; use evergreen ideas unless the reports support a timely angle' }}
